/* Tab «Sicherheitspunkte»: was vor dem Einstecken angeschaut wird. «Gilt für» hat genau die Werte aus GILT (ueberblick_). */
const GILT = ['Elektrogeräte', 'Mit Netzstecker', 'Mit Ladegerät', 'Mit Akku'];
