  [CH_PUNKT, 'Mit Netzstecker'],
  ['Ladegerät und Ladekabel ohne Schäden', 'Mit Ladegerät'],
  [CH_PUNKT, 'Mit Ladegerät'],
  ['Gehäuse ohne Risse und offene Stellen', 'Elektrogeräte'],
